from pysat.solvers import Glucose3

solver = Glucose3()

# Variables: edge (i, j) -> i * 8 + j (just need a unique ID from 1 to 28)
def var(i, j):
    # i < j
    # 0 <= i < j <= 7
    # index in lexicographic order:
    # i=0: 7 edges
    # i=1: 6 edges
    # ...
    idx = 0
    for a in range(i):
        idx += 7 - a
    idx += (j - i)
    return idx

# No red K3 (0 is red, so cannot be all False -> at least one True)
for i in range(8):
    for j in range(i+1, 8):
        for k in range(j+1, 8):
            solver.add_clause([var(i, j), var(j, k), var(i, k)])

# No blue K4 (1 is blue, so cannot be all True -> at least one False)
for i in range(8):
    for j in range(i+1, 8):
        for k in range(j+1, 8):
            for l in range(k+1, 8):
                solver.add_clause([-var(i, j), -var(i, k), -var(i, l), -var(j, k), -var(j, l), -var(k, l)])

if solver.solve():
    model = solver.get_model()
    colors = []
    for i in range(8):
        for j in range(i+1, 8):
            v = var(i, j)
            colors.append(1 if model[v-1] > 0 else 0)
    print(colors)
else:
    print("UNSATISFIABLE")

